PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,display_name TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user','moderator','admin')),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')),created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS categories(id TEXT PRIMARY KEY NOT NULL,slug TEXT NOT NULL UNIQUE,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS topics(id TEXT PRIMARY KEY NOT NULL,author_id TEXT NOT NULL REFERENCES users(id),category_id TEXT NOT NULL REFERENCES categories(id),slug TEXT NOT NULL UNIQUE,title TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','pending','published','hidden')),pinned INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS topics_feed_idx ON topics(status,created_at);
CREATE TABLE IF NOT EXISTS replies(id TEXT PRIMARY KEY NOT NULL,topic_id TEXT NOT NULL REFERENCES topics(id),author_id TEXT NOT NULL REFERENCES users(id),body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','published','hidden')),created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS replies_topic_idx ON replies(topic_id,created_at);
CREATE TABLE IF NOT EXISTS reactions(user_id TEXT NOT NULL REFERENCES users(id),topic_id TEXT NOT NULL REFERENCES topics(id),type TEXT NOT NULL CHECK(type IN ('like','bookmark')),created_at INTEGER NOT NULL,UNIQUE(user_id,topic_id,type));
CREATE TABLE IF NOT EXISTS invitations(id TEXT PRIMARY KEY NOT NULL,code_hash TEXT NOT NULL UNIQUE,issued_by TEXT REFERENCES users(id),used_by TEXT REFERENCES users(id),expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY NOT NULL,user_id TEXT NOT NULL REFERENCES users(id),token_hash TEXT NOT NULL UNIQUE,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY NOT NULL,reporter_id TEXT NOT NULL REFERENCES users(id),topic_id TEXT REFERENCES topics(id),reply_id TEXT REFERENCES replies(id),reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved','dismissed')),created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs(id TEXT PRIMARY KEY NOT NULL,actor_id TEXT REFERENCES users(id),action TEXT NOT NULL,target_type TEXT NOT NULL,target_id TEXT NOT NULL,metadata TEXT,created_at INTEGER NOT NULL);
